// The speaker: a MAX98357A I2S amplifier and a small 4 ohm speaker. The board sends numbers, the
// amplifier turns them into sound. No DAC, no analog wire: I2S carries 16-bit samples, the MAX98357A
// switches the speaker on and off very fast (class D) in proportion to each number.
//
// A task on core 0 renders 256 samples at a time (16 ms at 16 kHz) and hands them to the I2S DMA.
// i2s_channel_write() waits while the DMA is full, so the task runs exactly as fast as the speaker
// plays. What it mixes:
//   - a tone or a tune (synth.h Voice + Tune), queued from any task with tone() / tune()
//   - recorded samples (synth.h Player): play(), at any speed (pitch). The caller keeps the samples
//     alive until playing() turns false.
//   - a live stream (stream()): S8's voice effects push processed microphone samples here.
//
// Echo guard: the microphone hears the speaker. recentlyLoud() says whether anything audible left
// the speaker in the last few hundred ms, so the lab shell can stop the clap/knock detectors from
// hearing the board's own beeps.
//
// Nothing wired? Then the numbers go nowhere and nothing happens: every lab works without it.
#pragma once

#include <Arduino.h>
#include <driver/i2s_std.h>
#include <esp_heap_caps.h>
#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>

#include <algorithm>
#include <atomic>

#include "pins.h"
#include "synth.h"

namespace snd {

class Speaker {
 public:
  static constexpr uint32_t kRate = 16000;
  static constexpr int kBlock = 256;

  bool begin() {
    i2s_chan_config_t cc = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_1, I2S_ROLE_MASTER);
    cc.dma_frame_num = kBlock;
    cc.auto_clear_after_cb = true;  // if we ever fall behind, the DMA plays silence, not the last block again
    if (i2s_new_channel(&cc, &tx_, nullptr) != ESP_OK) return log_e("Speaker: no I2S channel"), false;
    i2s_std_config_t sc = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(kRate),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_16BIT, I2S_SLOT_MODE_STEREO),
        .gpio_cfg = {.mclk = I2S_GPIO_UNUSED, .bclk = gpio_num_t(PIN_I2S_SPK_BCLK), .ws = gpio_num_t(PIN_I2S_SPK_LRC),
                     .dout = gpio_num_t(PIN_I2S_SPK_DIN), .din = I2S_GPIO_UNUSED, .invert_flags = {}},
    };
    // Stereo, the same sample in left and right: the amplifier's (L+R)/2 mix (SD unconnected) plays it either way.
    if (i2s_channel_init_std_mode(tx_, &sc) != ESP_OK || i2s_channel_enable(tx_) != ESP_OK) return log_e("Speaker: I2S set-up failed"), false;
    cmds_ = xQueueCreate(24, sizeof(Cmd));
    streamBuf_ = static_cast<int16_t *>(heap_caps_calloc(kStream, sizeof(int16_t), MALLOC_CAP_SPIRAM));
    if (!cmds_ || !streamBuf_) return log_e("Speaker: no memory"), false;
    xTaskCreatePinnedToCore(task, "speaker", 4096, this, 4, nullptr, 0);
    log_i("Speaker: MAX98357A on I2S (BCLK %d, LRC %d, DIN %d) at %lu Hz", PIN_I2S_SPK_BCLK, PIN_I2S_SPK_LRC, PIN_I2S_SPK_DIN,
          static_cast<unsigned long>(kRate));
    return true;
  }

  // 0-100. Loudness grows with the square: 50 sounds about half as loud as 100.
  void setVolume(int v) { volume_ = v < 0 ? 0 : v > 100 ? 100 : v; }
  int volume() const { return volume_; }

  // ---- What to play (from any task) ------------------------------------------------------------

  void tone(float hz, uint32_t ms, syn::Wave wave = syn::Wave::Sine, float level = 0.8f) {
    Cmd c{Cmd::Tone};
    c.hz = hz, c.ms = float(ms), c.wave = wave, c.level = level;
    send(c);
  }
  // A melody in Tune's text format. The text must stay alive while it plays (string literals do).
  void tune(const char *text, int bpm = 140, syn::Wave wave = syn::Wave::Triangle) {
    Cmd c{Cmd::Tune};
    c.text = text, c.bpm = bpm, c.wave = wave;
    send(c);
  }
  // Recorded samples at `step` x speed. They must stay alive until playing() is false.
  void play(const int16_t *samples, uint32_t count, float step = 1.0f, float gain = 1.0f) {
    Cmd c{Cmd::Play};
    c.samples = samples, c.count = count, c.step = step, c.level = gain;
    playing_ = true;  // at once, so the caller's next playing() check already says yes
    send(c);
  }
  void stop() { send(Cmd{Cmd::Stop}); }

  bool busy() const { return busy_; }
  bool playing() const { return playing_; }
  float progress() const { return progress_; }
  // Was anything audible sent in the last `ms`? (the echo guard)
  bool recentlyLoud(uint32_t ms = 250) const { return millis() - lastLoudMs_ < ms; }
  // The loudest output sample of the last block, 0-1 (for a meter).
  float outputLevel() const { return outLevel_; }

  // ---- Live stream (S8) ------------------------------------------------------------------------

  // Push samples to play as soon as possible. Single producer (loop()), the speaker task consumes.
  // Returns how many fitted; the rest are dropped (the stream is ~0.5 s deep).
  uint32_t stream(const int16_t *s, uint32_t n) {
    const uint32_t w = sw_.load(std::memory_order_relaxed), r = sr_.load(std::memory_order_acquire);
    const uint32_t room = kStream - 1 - (w - r);
    if (n > room) n = room;
    for (uint32_t i = 0; i < n; i++) streamBuf_[(w + i) & (kStream - 1)] = s[i];
    sw_.store(w + n, std::memory_order_release);
    return n;
  }
  uint32_t streamQueued() const { return sw_.load(std::memory_order_acquire) - sr_.load(std::memory_order_acquire); }

 private:
  struct Cmd {
    enum Kind : uint8_t { Tone, Tune, Play, Stop } kind;
    syn::Wave wave = syn::Wave::Sine;
    float hz = 0, ms = 0, level = 1, step = 1;
    const char *text = nullptr;
    int bpm = 140;
    const int16_t *samples = nullptr;
    uint32_t count = 0;
  };
  static constexpr uint32_t kStream = 8192;

  void send(const Cmd &c) {
    if (cmds_ && xQueueSend(cmds_, &c, 0) != pdTRUE) log_w("Speaker: too many sounds queued");
  }

  static void task(void *arg) { static_cast<Speaker *>(arg)->run(); }

  void apply(const Cmd &c) {
    const syn::Envelope env;
    switch (c.kind) {
      case Cmd::Tone:
        tune_.set(nullptr, 0);
        voice_.start(c.hz, c.ms, c.wave, env, kRate, c.level);
        break;
      case Cmd::Tune:
        tune_.set(c.text, c.bpm);
        tuneWave_ = c.wave;
        voice_ = syn::Voice{};
        break;
      case Cmd::Play: player_.set(c.samples, c.count, c.step, c.level); break;
      case Cmd::Stop:
        tune_.set(nullptr, 0);
        voice_ = syn::Voice{};
        player_.stop();
        sr_.store(sw_.load(std::memory_order_acquire), std::memory_order_release);
        break;
    }
  }

  void run() {
    static int16_t out[kBlock * 2];  // left + right
    for (;;) {
      Cmd c;
      while (xQueueReceive(cmds_, &c, 0) == pdTRUE) apply(c);
      // The tune hands the voice its next note when the last one has finished.
      if (!voice_.active() && !tune_.done()) {
        float hz = 0, ms = 0;
        if (tune_.next(hz, ms)) {
          syn::Envelope env;
          env.releaseMs = std::min(90.0f, ms * 0.3f);
          voice_.start(hz, ms - env.releaseMs, tuneWave_, env, kRate, 0.7f);
        }
      }
      const float gain = (volume_ / 100.0f) * (volume_ / 100.0f) * 32000.0f;
      float peak = 0;
      const uint32_t w = sw_.load(std::memory_order_acquire);
      uint32_t r = sr_.load(std::memory_order_relaxed);
      for (int i = 0; i < kBlock; i++) {
        float v = voice_.next() + player_.next();
        if (r != w) v += streamBuf_[r++ & (kStream - 1)] / 32768.0f;
        v = syn::softClip(v);
        peak = std::max(peak, fabsf(v));
        out[2 * i] = out[2 * i + 1] = int16_t(v * gain);
      }
      sr_.store(r, std::memory_order_release);
      outLevel_ = peak;
      if (peak * gain > 300) lastLoudMs_ = millis();
      busy_ = voice_.active() || !tune_.done() || player_.active() || r != sw_.load(std::memory_order_acquire);
      playing_ = player_.active();
      progress_ = player_.progress();
      size_t done = 0;
      i2s_channel_write(tx_, out, sizeof(out), &done, portMAX_DELAY);  // waits for room: this is the clock
    }
  }

  i2s_chan_handle_t tx_ = nullptr;
  QueueHandle_t cmds_ = nullptr;
  syn::Voice voice_;
  syn::Tune tune_;
  syn::Wave tuneWave_ = syn::Wave::Triangle;
  syn::Player player_;
  int16_t *streamBuf_ = nullptr;
  std::atomic<uint32_t> sw_{0}, sr_{0};
  volatile int volume_ = 40;
  volatile bool busy_ = false, playing_ = false;
  volatile float progress_ = 0, outLevel_ = 0;
  volatile uint32_t lastLoudMs_ = 0;
};

}  // namespace snd

// Our own off-screen picture, drawn with the normal Adafruit GFX calls.
//
// Lesson 03 used GFXcanvas16, which always lands in PSRAM (big but slow memory outside the chip).
// Here we choose: fast internal RAM when a big enough block is free, PSRAM otherwise.
// The serial log at start-up tells you which one you got.
#pragma once

#include <Adafruit_GFX.h>
#include <esp_heap_caps.h>

#include <algorithm>

class FrameBuffer : public Adafruit_GFX {
 public:
  FrameBuffer(int16_t w, int16_t h) : Adafruit_GFX(w, h) {}
  ~FrameBuffer() override { heap_caps_free(buf_); }

  bool begin() {
    const size_t bytes = bytesUsed();
    buf_ = static_cast<uint16_t *>(heap_caps_malloc(bytes, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
    internal_ = buf_ != nullptr;
    if (buf_ == nullptr) buf_ = static_cast<uint16_t *>(heap_caps_malloc(bytes, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT));
    return buf_ != nullptr;
  }

  bool internal() const { return internal_; }
  size_t bytesUsed() const { return size_t(WIDTH) * HEIGHT * sizeof(uint16_t); }
  uint16_t *pixels() { return buf_; }

  // ---- The minimum Adafruit GFX needs (drawPixel) plus fast paths for lines and fills ----

  void drawPixel(int16_t x, int16_t y, uint16_t c) override {
    if (x < 0 || y < 0 || x >= _width || y >= _height) return;
    buf_[y * _width + x] = c;
  }

  void fillScreen(uint16_t c) override { std::fill_n(buf_, size_t(_width) * _height, c); }

  void drawFastHLine(int16_t x, int16_t y, int16_t w, uint16_t c) override {
    if (w < 0) x += w + 1, w = -w;
    if (y < 0 || y >= _height) return;
    if (x < 0) w += x, x = 0;
    if (x + w > _width) w = _width - x;
    if (w > 0) std::fill_n(buf_ + y * _width + x, w, c);
  }

  void drawFastVLine(int16_t x, int16_t y, int16_t h, uint16_t c) override {
    if (h < 0) y += h + 1, h = -h;
    if (x < 0 || x >= _width) return;
    if (y < 0) h += y, y = 0;
    if (y + h > _height) h = _height - y;
    for (uint16_t *p = buf_ + y * _width + x; h-- > 0; p += _width) *p = c;
  }

  void fillRect(int16_t x, int16_t y, int16_t w, int16_t h, uint16_t c) override {
    for (int16_t j = 0; j < h; j++) drawFastHLine(x, y + j, w, c);
  }

 private:
  uint16_t *buf_ = nullptr;
  bool internal_ = false;
};

// Colour helpers for the 16-bit RGB565 format the ST7789 speaks: 5 bits red, 6 green, 5 blue.
#pragma once

#include <stdint.h>

constexpr uint16_t rgb(uint8_t r, uint8_t g, uint8_t b) {
  return uint16_t(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

// Hue 0-255 around the colour wheel, saturation and value 0-255.
inline uint16_t hsv(uint8_t h, uint8_t s, uint8_t v) {
  const uint8_t region = h / 43;
  const uint8_t rem = (h - region * 43) * 6;
  const uint8_t p = (v * (255 - s)) >> 8;
  const uint8_t q = (v * (255 - ((s * rem) >> 8))) >> 8;
  const uint8_t t = (v * (255 - ((s * (255 - rem)) >> 8))) >> 8;
  switch (region) {
    case 0: return rgb(v, t, p);
    case 1: return rgb(q, v, p);
    case 2: return rgb(p, v, t);
    case 3: return rgb(p, q, v);
    case 4: return rgb(t, p, v);
    default: return rgb(v, p, q);
  }
}

// Mix two colours: k = 0 gives a, k = 255 gives b.
inline uint16_t mix(uint16_t a, uint16_t b, uint8_t k) {
  const int ar = a >> 11, ag = (a >> 5) & 63, ab = a & 31;
  const int br = b >> 11, bg = (b >> 5) & 63, bb = b & 31;
  return uint16_t(((ar + ((br - ar) * k >> 8)) << 11) | ((ag + ((bg - ag) * k >> 8)) << 5) | (ab + ((bb - ab) * k >> 8)));
}

// The palette every scene shares, so the showcase reads as one piece.
namespace pal {
constexpr uint16_t ink = rgb(232, 238, 246);
constexpr uint16_t muted = rgb(118, 138, 162);
constexpr uint16_t dim = rgb(34, 46, 62);
constexpr uint16_t night = rgb(10, 14, 22);
constexpr uint16_t teal = rgb(70, 220, 190);
constexpr uint16_t amber = rgb(255, 176, 60);
constexpr uint16_t coral = rgb(255, 96, 84);
}  // namespace pal

// Making sound from numbers: the pieces the speaker (speaker.h) mixes, 16 000 samples a second.
//
//   Voice    one note: an oscillator (sine, square, triangle, saw, noise) shaped by an envelope.
//            ADSR = attack (fade in), decay (fall to the sustain level), sustain (hold), release
//            (fade out). Without it every note starts and stops with a click.
//   Tune     a melody as text: "C5/8 E5/8 G5/4 r/8 C6/2." = note + octave, / length (4 = quarter,
//            8 = eighth), a dot makes it 1.5x longer, r = rest. Tempo in beats per minute.
//   Player   plays recorded samples, at any speed: step 1.5 plays 1.5x faster, so 1.5x higher
//            (the chipmunk). Between two samples it draws a straight line (linear interpolation).
//
// Everything works in floats from -1 to +1; the speaker turns them into 16-bit numbers at the end.
// Pure C++ (no Arduino): host-tested in kit/test/host/sound_synth_test.cpp.
#pragma once

#include <ctype.h>
#include <math.h>
#include <stdint.h>
#include <stdlib.h>
#include <strings.h>

namespace syn {

enum class Wave : uint8_t { Sine, Square, Triangle, Saw, Noise };

inline const char *waveName(Wave w) {
  switch (w) {
    case Wave::Square: return "square";
    case Wave::Triangle: return "triangle";
    case Wave::Saw: return "saw";
    case Wave::Noise: return "noise";
    default: return "sine";
  }
}

inline bool parseWave(const char *s, Wave &out) {
  static const char *const kNames[] = {"sine", "square", "triangle", "saw", "noise"};
  for (int i = 0; i < 5; i++)
    if (strcasecmp(s, kNames[i]) == 0) return out = Wave(i), true;
  return false;
}

// "A4" = 440 Hz, "C#5", "Bb3". 0 for a rest ("r") or anything we can't read.
inline float noteHz(const char *name, float a4 = 440.0f) {
  if (!name || !name[0]) return 0;
  static const int kSemis[] = {9, 11, 0, 2, 4, 5, 7};  // A B C D E F G from C
  const char letter = char(toupper(name[0]));
  if (letter < 'A' || letter > 'G') return 0;
  int semi = kSemis[letter - 'A'], i = 1;
  if (name[i] == '#') semi++, i++;
  else if (name[i] == 'b') semi--, i++;
  if (!isdigit(name[i])) return 0;
  const int octave = name[i] - '0';
  const int midi = (octave + 1) * 12 + semi;
  return a4 * powf(2.0f, (midi - 69) / 12.0f);
}

struct Envelope {
  float attackMs = 6, decayMs = 80, sustain = 0.65f, releaseMs = 90;
};

class Voice {
 public:
  void start(float hz, float durMs, Wave w, const Envelope &env, float rate, float level = 1.0f) {
    hz_ = hz, wave_ = w, env_ = env, rate_ = rate, level_ = level;
    phase_ = 0;
    t_ = 0;
    dur_ = durMs * rate / 1000.0f;
    active_ = hz > 0 || w == Wave::Noise;
    silentUntil_ = active_ ? 0 : dur_;  // a rest still takes its time
  }
  void release() { dur_ = t_; }
  bool active() const { return active_ || t_ < silentUntil_; }
  float hz() const { return hz_; }

  float next() {
    if (!active_) {
      t_++;
      return 0;
    }
    const float ms = t_ * 1000.0f / rate_;
    const float relMs = t_ > dur_ ? (t_ - dur_) * 1000.0f / rate_ : 0;
    float a;
    if (relMs > 0) a = sustainAt(dur_ * 1000.0f / rate_) * (1.0f - relMs / env_.releaseMs);
    else a = sustainAt(ms);
    if (relMs >= env_.releaseMs || (relMs > 0 && a <= 0)) {  // a = 0 at the very start is the attack, not the end
      active_ = false;
      return 0;
    }
    t_++;
    phase_ += hz_ / rate_;
    phase_ -= floorf(phase_);
    return osc() * a * level_;
  }

 private:
  // The envelope level `ms` into the note, before the release.
  float sustainAt(float ms) const {
    if (ms < env_.attackMs) return ms / env_.attackMs;
    if (ms < env_.attackMs + env_.decayMs) return 1.0f - (1.0f - env_.sustain) * (ms - env_.attackMs) / env_.decayMs;
    return env_.sustain;
  }

  float osc() {
    switch (wave_) {
      case Wave::Square: return phase_ < 0.5f ? 0.6f : -0.6f;  // squares sound twice as loud: tamed
      case Wave::Triangle: return phase_ < 0.5f ? 4 * phase_ - 1 : 3 - 4 * phase_;
      case Wave::Saw: return (2 * phase_ - 1) * 0.7f;
      case Wave::Noise: noise_ = noise_ * 1664525u + 1013904223u; return (int32_t(noise_) >> 8) / 8388608.0f * 0.5f;
      default: return sinf(6.2831853f * phase_);
    }
  }

  float hz_ = 0, rate_ = 16000, level_ = 1, phase_ = 0, t_ = 0, dur_ = 0, silentUntil_ = 0;
  Wave wave_ = Wave::Sine;
  Envelope env_;
  bool active_ = false;
  uint32_t noise_ = 22222;
};

// Reads "C5/8 E5/8 G5/4 r/8 C6/2." one note at a time.
class Tune {
 public:
  void set(const char *text, int bpm) {
    text_ = at_ = text;
    bpm_ = bpm > 0 ? bpm : 120;
  }
  bool done() const { return !at_ || !*at_; }

  // The next note: false at the end. hz = 0 for a rest. ms = how long it lasts.
  bool next(float &hz, float &ms) {
    if (!at_) return false;
    while (*at_ == ' ' || *at_ == ',') at_++;
    if (!*at_) return false;
    char name[6] = {};
    int n = 0;
    while (*at_ && *at_ != '/' && *at_ != ' ' && n < 5) name[n++] = *at_++;
    int len = 4;
    if (*at_ == '/') len = int(strtol(at_ + 1, const_cast<char **>(&at_), 10));
    if (len <= 0) len = 4;
    float beats = 4.0f / len;
    if (*at_ == '.') beats *= 1.5f, at_++;
    while (*at_ && *at_ != ' ') at_++;  // skip anything we don't understand
    hz = (name[0] == 'r' || name[0] == 'R') ? 0 : noteHz(name);
    ms = beats * 60000.0f / bpm_;
    return true;
  }

 private:
  const char *text_ = nullptr, *at_ = nullptr;
  int bpm_ = 120;
};

class Player {
 public:
  void set(const int16_t *samples, uint32_t count, float step = 1.0f, float gain = 1.0f) {
    s_ = samples, n_ = count, step_ = step, gain_ = gain, pos_ = 0;
  }
  void stop() { n_ = 0; }
  bool active() const { return s_ && pos_ + 1 < n_; }
  float progress() const { return n_ ? float(pos_) / n_ : 0; }

  float next() {
    if (!active()) return 0;
    const uint32_t i = uint32_t(pos_);
    const float frac = float(pos_ - i);
    const float v = s_[i] + (s_[i + 1] - s_[i]) * frac;
    pos_ += step_;
    return v / 32768.0f * gain_;
  }

 private:
  const int16_t *s_ = nullptr;
  uint32_t n_ = 0;
  double pos_ = 0;
  float step_ = 1, gain_ = 1;
};

// Keeps the sum of several sounds inside -1..+1 without the harsh edge of plain clipping.
inline float softClip(float x) { return x > 1 ? 1 : x < -1 ? -1 : x * (1.5f - 0.5f * x * x); }

